[214] tool shell_command call: {"command":"$js = @"
const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

class ProxyAgent extends https.Agent {
  constructor(proxyUrl) {
    super();
    this.proxyUrl = new URL(proxyUrl);
  }
  createConnection(options, oncreate) {
    const host = options.host || options.hostname;
    const port = options.port || 443;
    const proxyReq = http.request({
      hostname: this.proxyUrl.hostname,
      port: this.proxyUrl.port,
      path: `${host}:${port}`,
      method: 'CONNECT',
    });
    proxyReq.on('connect', (res, socket) => oncreate(res.statusCode === 200 ? socket : null));
    proxyReq.end();
  }
}

const root = process.cwd();
const filesToDeploy = [
  'package.json', 'tsconfig.json', 'next.config.mjs', 
  'postcss.config.mjs', 'src/app/page.tsx', 'src/app/layout.tsx', 
  'robots.txt'
];

const imagesDir = path.join(root, 'public', 'images');
if (fs.existsSync(imagesDir)) {
  fs.readdirSync(imagesDir).forEach(f => filesToDeploy.push('public/images/' + f));
}

const payloadFiles = [];
for (const f of filesToDeploy) {
  const fp = path.join(root, f);
  if (!fs.existsSync(fp)) continue;
  const stat = fs.statSync(fp);
  const isBinary = /\.(jpg|png|gif|jpeg)$/i.test(f);
  let data = "";
  if (isBinary) {
    data = fs.readFileSync(fp).toString('base64');
  } else {
    try {
      let raw = fs.readFileSync(fp, 'utf8');
      if (raw.charCodeAt(0) === 0xFEFF) raw = raw.slice(1);
      data = raw;
    } catch(e) { data = ""; };
  }
  payloadFiles.push({ path: f, data, size: stat.size });
}

console.log(`Uploading ${payloadFiles.length} files to Vercel API via proxy...`);
const body = JSON.stringify({ name: 'personal-website', framework: 'next.js', files: payloadFiles });
const agent = new ProxyAgent('http://127.0.0.1:7897');

const req = https.request({
  hostname: 'api.vercel.com',
  path: '/v6/deployments?teamId=team_NGXWfFxSgU04Qc4U9AlWlHGT',
  method: 'POST',
  agent: agent,
  headers: { 
    'Authorization': 'Bearer vcp_3ljUZJTreQQZOoC7qYYtYb0AB1JGV6UqTjQ0nyDCwCzW0f334501sy6p',
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(body)
  }
}, res => {
  let rawData = '';
  res.on('data', chunk => rawData += chunk);
  res.on('end', () => {
    try {
      const json = JSON.parse(rawData);
      if (res.statusCode === 200) {
        console.log("Success! Deployment ID:", json.id);
        process.exit(0);
      } else {
        console.error("Error", res.statusCode, JSON.stringify(json));
        process.exit(1);
      }
    } catch(e) { 
      console.error("Parse Error:", rawData.substring(0, 200)); 
      process.exit(1);
    }
  });
});

req.on('error', e => {
  console.error("Request Error:", e.message);
  process.exit(1);
});

req.write(body);
req.end();
